fn fibonacci(n: Int) -> Vec[Int] {
  let v = Vec[Int]().with_capacity(n);
  if n >= 1 { v.push(0); }
  if n >= 2 { v.push(1); }
  var i = 2;
  while i < n {
    v.push(v[i - 1] + v[i - 2]);
    i = i + 1;
  }
  return v;
}

fn range(start: Int, end: Int) -> Vec[Int] {
  let v = Vec[Int]().with_capacity(end - start);
  var i = start;
  while i < end {
    v.push(i);
    i = i + 1;
  }
  return v;
}

fn main() -> Int {
  let fib = fibonacci(10);
  return fib[9];
}
